import{_ as e,c as t,o as d,b2 as r}from"./chunks/framework.CUhoHPxN.js";const p=JSON.parse('{"title":"C7Title（C7 标题）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-07-c7-title-design.md","filePath":"superpowers/specs/2026-05-07-c7-title-design.md"}'),s={name:"superpowers/specs/2026-05-07-c7-title-design.md"};function n(c,o,a,l,i,g){return d(),t("div",null,[...o[0]||(o[0]=[r(`<h1 id="c7title-c7-标题-设计说明" tabindex="-1">C7Title（C7 标题）设计说明 <a class="header-anchor vp-link" href="#c7title-c7-标题-设计说明" aria-label="Permalink to &quot;C7Title（C7 标题）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-07<br><strong>状态</strong>：已定稿（经 brainstorming 澄清与「设计批准」）<br><strong>依据</strong>：<code>原始需求/前端/C7标题.md</code> + Q&amp;A 结论（1B、2A、3A、4A、5A、6A）</p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>页面区块标题需统一：<strong>字号、加粗、底部装饰线、左侧图标、右侧操作区</strong>，且可通过 <strong>语义标签</strong> 与 <strong>CSS 变量</strong> 控制装饰色。</p><hr><h2 id="_2-组件边界" tabindex="-1">2. 组件边界 <a class="header-anchor vp-link" href="#_2-组件边界" aria-label="Permalink to &quot;2. 组件边界&quot;">​</a></h2><ul><li><strong>职责</strong>：独立用于<strong>页面 / 表单分块</strong>标题条；<strong>不</strong>承担 Card 容器职责。</li><li><strong>与 <code>C7Card</code></strong>：<strong>解耦</strong>，不抽取共享子组件；允许与 Card 在 <strong>CSS 变量命名习惯</strong> 上对齐（如 <code>--c7-title-decoration-color</code>），<strong>不要求</strong>改动 <code>C7Card</code>。</li><li><strong>非目标</strong>：路由、权限、数据请求；右侧内容由默认插槽完全由业务提供。</li></ul><hr><h2 id="_3-技术选型-已定稿" tabindex="-1">3. 技术选型（已定稿） <a class="header-anchor vp-link" href="#_3-技术选型-已定稿" aria-label="Permalink to &quot;3. 技术选型（已定稿）&quot;">​</a></h2><ul><li><strong>标题节点</strong>：使用 <strong><code>ElText</code></strong>，<code>:tag=&quot;resolvedTag&quot;</code>，与 <code>C7Card</code> 标题语义路径一致。</li><li><strong>图标</strong>：<code>import * as ElementPlusIconsVue from &#39;@element-plus/icons-vue&#39;</code>，按 <strong>PascalCase 字符串</strong> 动态解析；未找到组件时 <strong><code>console.warn</code></strong> 且不渲染图标。</li><li><strong>底部线</strong>：<strong>装饰线与 <code>showBorder</code> 为同一视觉元素</strong>；<code>showBorder === false</code> 时不显示。</li></ul><hr><h2 id="_4-对外-api" tabindex="-1">4. 对外 API <a class="header-anchor vp-link" href="#_4-对外-api" aria-label="Permalink to &quot;4. 对外 API&quot;">​</a></h2><h3 id="_4-1-命名与注册" tabindex="-1">4.1 命名与注册 <a class="header-anchor vp-link" href="#_4-1-命名与注册" aria-label="Permalink to &quot;4.1 命名与注册&quot;">​</a></h3><ul><li>组件名：<strong><code>C7Title</code></strong></li><li>路径：<code>quick-ui/src/packages/C7Title/index.vue</code></li><li>在 <strong><code>quick-ui/src/packages/index.js</code></strong> 中导出并 <strong><code>installPackages</code></strong> 注册。</li></ul><h3 id="_4-2-根节点与透传" tabindex="-1">4.2 根节点与透传 <a class="header-anchor vp-link" href="#_4-2-根节点与透传" aria-label="Permalink to &quot;4.2 根节点与透传&quot;">​</a></h3><ul><li>根节点：<strong><code>div.c7-title</code></strong>（或带 BEM 根类名的容器），<strong>不</strong>使用会吞掉布局的单一 EP 表单控件作为根。</li><li><strong><code>defineOptions({ name: &#39;C7Title&#39;, inheritAttrs: true })</code></strong>：除下文显式 props 外，<strong><code>class</code> / <code>style</code> 等</strong> 绑定根节点，便于页面级微调。</li></ul><h3 id="_4-3-props" tabindex="-1">4.3 Props <a class="header-anchor vp-link" href="#_4-3-props" aria-label="Permalink to &quot;4.3 Props&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>Prop</th><th>类型 / 约束</th><th>说明</th></tr></thead><tbody><tr><td><strong><code>tag</code></strong></td><td><code>h1</code>~<code>h6</code>、<code>div</code>、<code>p</code></td><td>语义标签，<strong>默认 <code>h4</code></strong>（与 <code>C7Card</code> 默认标题层级对齐）。</td></tr><tr><td><strong><code>labelSize</code></strong></td><td><code>h1</code>~<code>h6</code> 或含单位的字符串（如 <code>20px</code>、<code>1.2rem</code>、<code>1.2em</code>）</td><td>若为 <strong><code>h1</code>~<code>h6</code></strong>：应用预设 <strong>字号 / 行高</strong>（及实现内与层级一致的排版）；且当调用方 <strong>未显式传入 <code>tag</code></strong>（即使用默认值）时，<strong>将 <code>resolvedTag</code> 设为与 <code>labelSize</code> 相同层级</strong>（1B）。若调用方 <strong>显式传入</strong> <code>tag</code>，<strong>不</strong>因 <code>labelSize</code> 为 h 级而改写 <code>tag</code>。若为 <strong>自定义单位字符串</strong>：仅设置 <strong><code>font-size</code></strong>（及合理 <strong><code>line-height</code></strong>），<strong>不改变</strong> <code>tag</code>。非法或无法解析的字符串：<strong>开发环境 <code>console.warn</code></strong>，字号回退为与默认 <code>tag</code> 对应的预设或实现约定基线。</td></tr><tr><td><strong><code>label</code></strong></td><td><code>string</code></td><td>主文案（6A）。</td></tr><tr><td><strong><code>title</code></strong></td><td><code>string</code></td><td><strong>兼容别名</strong>，语义同 <strong><code>label</code></strong>。<strong>若 <code>label</code> 与 <code>title</code> 同时传入</strong>：<strong>仅以 <code>label</code> 为准</strong>；若仅在开发环境检测到二者均有非空值，可 <strong><code>console.warn</code></strong> 一次。</td></tr><tr><td><strong><code>decorationColor</code></strong></td><td><code>string</code></td><td><strong>优先</strong>；用于底部线 / 装饰色，写入根节点 CSS 变量（见 4.5）。</td></tr><tr><td><strong><code>labelColor</code></strong></td><td><code>string</code></td><td><strong>兼容别名</strong>：仅当 <strong><code>decorationColor</code> 未传</strong>（<code>undefined</code>）时参与计算有效颜色。</td></tr><tr><td><strong><code>showBorder</code></strong></td><td><code>boolean</code>，默认 <strong><code>true</code></strong></td><td><strong><code>true</code></strong> 显示底部线；<strong><code>false</code></strong> 不显示（2A）。</td></tr><tr><td><strong><code>icon</code></strong></td><td><code>string</code>（EP 图标 PascalCase 名）</td><td>与 <strong><code>#icon</code></strong> 二选一优先级见插槽节。</td></tr></tbody></table></div><p><strong>字重</strong>：区块标题 <strong>固定 <code>font-weight: 600</code></strong>，<strong>不</strong>增加 <code>bold</code> prop（YAGNI）。</p><h3 id="_4-4-插槽" tabindex="-1">4.4 插槽 <a class="header-anchor vp-link" href="#_4-4-插槽" aria-label="Permalink to &quot;4.4 插槽&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>插槽</th><th>说明</th></tr></thead><tbody><tr><td><strong><code>icon</code></strong></td><td>若存在： <strong>完全覆盖</strong> <code>icon</code> 字符串解析结果，由业务自行放置 <code>el-icon</code> 等。</td></tr><tr><td><strong><code>title</code></strong></td><td>若存在：<strong>覆盖</strong> <code>label</code> / <code>title</code> prop 的文本渲染（支持富标题、多节点）。</td></tr><tr><td><strong>默认</strong></td><td><strong>右侧 actions 区</strong>；布局上使用 <strong>flex</strong>，<strong><code>margin-left: auto</code></strong> 或等价使主标题 + 图标靠左、操作区靠右。</td></tr></tbody></table></div><p><strong>图标显隐</strong>：存在 <strong><code>#icon</code></strong> 或 <strong><code>icon</code> 解析出有效组件</strong> 时显示图标区；否则不占位（避免空槽影响对齐时可不渲染图标容器）。</p><h3 id="_4-5-css-变量-验收-装饰线颜色可控" tabindex="-1">4.5 CSS 变量（验收：装饰线颜色可控） <a class="header-anchor vp-link" href="#_4-5-css-变量-验收-装饰线颜色可控" aria-label="Permalink to &quot;4.5 CSS 变量（验收：装饰线颜色可控）&quot;">​</a></h3><p>根节点设置至少：</p><ul><li><strong><code>--c7-title-decoration-color</code></strong>：有效值为 <strong><code>decorationColor</code> ?? <code>labelColor</code> ?? <code>var(--el-color-primary)</code></strong>（5A）。</li></ul><p>底部线（与装饰合一）使用该变量；<strong>高度约 <code>2px</code></strong>，<strong>宽度 100%</strong>（相对根容器）。</p><hr><h2 id="_5-布局结构-逻辑" tabindex="-1">5. 布局结构（逻辑） <a class="header-anchor vp-link" href="#_5-布局结构-逻辑" aria-label="Permalink to &quot;5. 布局结构（逻辑）&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>[根 .c7-title]</span></span>
<span class="line"><span>  [行：flex align-items center]</span></span>
<span class="line"><span>    [可选 图标区]</span></span>
<span class="line"><span>    [ElText：resolvedTag + 字号/加粗]</span></span>
<span class="line"><span>    [默认插槽：actions，ml-auto]</span></span>
<span class="line"><span>  [可选 底部线：showBorder]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="_6-labelsize-预设表-实现约束" tabindex="-1">6. <code>labelSize</code> 预设表（实现约束） <a class="header-anchor vp-link" href="#_6-labelsize-预设表-实现约束" aria-label="Permalink to &quot;6. \`labelSize\` 预设表（实现约束）&quot;">​</a></h2><ul><li>实现侧维护 <strong><code>h1</code>~<code>h6</code> → font-size / line-height</strong> 映射表；<strong>数值应对齐 Element Plus 文档中标题层级或设计稿</strong>，并在组件 JSDoc 中注明「与 EP 标题 token 对齐」或给出具体 rem/px。</li><li><strong>自定义单位</strong> 分支不修改 <strong><code>tag</code></strong>，仅覆盖字号相关样式。</li></ul><hr><h2 id="_7-无障碍" tabindex="-1">7. 无障碍 <a class="header-anchor vp-link" href="#_7-无障碍" aria-label="Permalink to &quot;7. 无障碍&quot;">​</a></h2><ul><li>标题层级由 <strong><code>resolvedTag</code></strong> 决定，勿为装饰目的滥用 <code>h1</code>。</li><li>右侧操作区为 <strong><code>div</code></strong> 包裹默认插槽即可；插槽内控件须自带可访问名称（与 <code>C7Card</code> 的 <code>extra</code> 约定一致）。</li></ul><hr><h2 id="_8-验收标准-与原始需求对齐" tabindex="-1">8. 验收标准（与原始需求对齐） <a class="header-anchor vp-link" href="#_8-验收标准-与原始需求对齐" aria-label="Permalink to &quot;8. 验收标准（与原始需求对齐）&quot;">​</a></h2><ul><li>不同 <strong><code>labelSize</code></strong>（<code>h1</code>~<code>h6</code> 与 <code>px</code>/<code>rem</code>/<code>em</code>）下标题字号/行高表现正确。</li><li><strong><code>decorationColor</code> / <code>labelColor</code></strong> 优先级正确；底部线颜色可通过根上 <strong>CSS 变量</strong> 在 DevTools 中验证。</li><li><strong><code>icon</code> + <code>#icon</code> 覆盖</strong>、<strong><code>#title</code> 覆盖</strong>、<strong>默认插槽右侧</strong> 行为符合第 4 节。</li><li><strong><code>showBorder</code></strong> 控制底部线显隐。</li></ul><hr><h2 id="_9-测试建议-实现阶段" tabindex="-1">9. 测试建议（实现阶段） <a class="header-anchor vp-link" href="#_9-测试建议-实现阶段" aria-label="Permalink to &quot;9. 测试建议（实现阶段）&quot;">​</a></h2><ul><li>组件级或 Story：<strong><code>labelSize</code></strong> 各分支；<strong>颜色优先级</strong>；<strong><code>showBorder</code></strong>；<strong>有效 / 无效 <code>icon</code> 字符串</strong>；<strong><code>#title</code> / <code>#icon</code> / 默认插槽</strong> 组合；<strong><code>label</code>+<code>title</code> 同时传</strong> 仅认 <code>label</code>。</li></ul><hr><h2 id="_10-澄清结论索引" tabindex="-1">10. 澄清结论索引 <a class="header-anchor vp-link" href="#_10-澄清结论索引" aria-label="Permalink to &quot;10. 澄清结论索引&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>题号</th><th>选项</th><th>含义摘要</th></tr></thead><tbody><tr><td>1</td><td>B</td><td><code>labelSize</code> 为 h 级时默认同步 <code>tag</code>，可被显式 <code>tag</code> 覆盖</td></tr><tr><td>2</td><td>A</td><td>装饰线与 <code>showBorder</code> 为同一元素</td></tr><tr><td>3</td><td>A</td><td>与 <code>C7Card</code> 独立，最多共享变量命名</td></tr><tr><td>4</td><td>A</td><td>PascalCase 动态映射 icons，未知 warn</td></tr><tr><td>5</td><td>A</td><td>默认主色变量，线高约 2px</td></tr><tr><td>6</td><td>A</td><td><code>label</code> 为主文案，<code>title</code> 别名；<code>#title</code> 可覆盖</td></tr></tbody></table></div>`,45)])])}const b=e(s,[["render",n]]);export{p as __pageData,b as default};
